import { RangeMan } from '@boss/h-table';
import { Operation, SortOperation } from '@bzl/sheet-js';
export const transSort = (
  leftOp: SortOperation,
  rightOp: Operation,
  side?: 'right' | 'left',
): Operation[] => {
  const { range, sortBy, before, after } = leftOp;
  const effectRange = sortBy === 'sheet' ? [0, range[1], Infinity, range[3]] : range;
  switch (rightOp.type) {
    case 'insert-row': {
      const insertRowRange = [0, rightOp.at, Infinity, rightOp.at + rightOp.count - 1];
      if (rightOp.at < range[3]) {
        // 偏移行号
        const newAfter = after.map((rowIndex) =>
          rowIndex >= rightOp.at ? rowIndex + rightOp.count : rowIndex,
        );
        const newBefore = before.map((rowIndex) =>
          rowIndex >= rightOp.at ? rowIndex + rightOp.count : rowIndex,
        );
        if (rightOp.at > range[1]) {
          const insertIndex = new Array(rightOp.count).fill(0).map((_, idx) => rightOp.at + idx);
          newBefore.splice(rightOp.at, 0, ...insertIndex);
        }
        const newRange = RangeMan.applyInsertRow(leftOp.range, {
          at: rightOp.at,
          count: rightOp.count,
        });
        return [
          {
            ...leftOp,
            range: newRange,
            after: newAfter,
            before: newBefore,
          },
        ];
      } else {
        return [leftOp];
      }
    }
    case 'remove-row': {
      const removeRowRange = [0, rightOp.at, Infinity, rightOp.at + rightOp.count - 1];
      if (RangeMan.isFullOverlapping(removeRowRange, effectRange)) {
        return [];
      }
      if (RangeMan.isOverlapping(removeRowRange, effectRange)) {
        // 移除掉被删除的行号
        const newAfter = after
          .filter((rowIndex) => rowIndex < rightOp.at || rowIndex >= rightOp.at + rightOp.count)
          .map((rowIndex) =>
            rowIndex >= rightOp.at + rightOp.count ? rowIndex - rightOp.count : rowIndex,
          );
        const newBefore = before
          .filter((r) => r < rightOp.at || r >= rightOp.at + rightOp.count)
          .map((rowIndex) =>
            rowIndex >= rightOp.at + rightOp.count ? rowIndex - rightOp.count : rowIndex,
          );
        const newRange = RangeMan.applyRemoveRow(leftOp.range, {
          at: rightOp.at,
          count: rightOp.count,
        });
        return newRange
          ? [
              {
                ...leftOp,
                range: newRange,
                after: newAfter,
                before: newBefore,
              },
            ]
          : [];
      } else {
        return [leftOp];
      }
    }
    case 'insert-col': {
      if (leftOp.sortBy === 'sheet') {
        return [leftOp];
      }
      const range = RangeMan.applyInsertCol(leftOp.range, { at: rightOp.at, count: rightOp.count });

      return [
        {
          ...leftOp,
          range,
        },
      ];
    }
    case 'remove-col': {
      if (leftOp.sortBy === 'sheet') {
        return [leftOp];
      }
      const range = RangeMan.applyRemoveCol(leftOp.range, { at: rightOp.at, count: rightOp.count });
      return range
        ? [
            {
              ...leftOp,
              range,
            },
          ]
        : [];
    }
    default:
      return [leftOp];
  }
};
