import { RangeMan } from '@boss/h-table';
import { Operation, UpdateMergeCellOperation } from '@bzl/sheet-js';

export const transMergeCell = (
  leftOp: UpdateMergeCellOperation,
  rightOp: Operation,
  side: 'right' | 'left',
): UpdateMergeCellOperation[] => {
  switch (rightOp.type) {
    case 'insert-col': {
      if (!leftOp.newV) return [leftOp];
      const newRange = RangeMan.applyInsertCol(leftOp.newV, {
        at: rightOp.at,
        count: rightOp.count,
      });

      return [
        {
          ...leftOp,
          newV: newRange,
        },
      ];
    }

    case 'remove-col': {
      if (!leftOp.newV) return [leftOp];
      const newRange = RangeMan.applyRemoveCol(
        leftOp.newV,
        {
          at: rightOp.at,
          count: rightOp.count,
        },
        false,
      );
      if (newRange) {
        return [
          {
            ...leftOp,
            newV: newRange,
          },
        ];
      }
      return [];
    }
    case 'insert-row': {
      if (!leftOp.newV) return [leftOp];
      const newRange = RangeMan.applyInsertRow(leftOp.newV, {
        at: rightOp.at,
        count: rightOp.count,
      });
      if (newRange) {
        return [
          {
            ...leftOp,
            newV: newRange,
          },
        ];
      }
      return [];
    }
    case 'remove-row': {
      if (!leftOp.newV) return [leftOp];
      const newRange = RangeMan.applyRemoveRow(
        leftOp.newV,
        {
          at: rightOp.at,
          count: rightOp.count,
        },
        false,
      );
      if (newRange) {
        return [
          {
            ...leftOp,
            newV: newRange,
          },
        ];
      }
      return [];
    }
    case 'update-merge': {
      if (leftOp.id === rightOp.id) {
        return side === 'left' ? [leftOp] : [rightOp];
      }
      if (leftOp.newV && rightOp.newV && RangeMan.isOverlapping(leftOp.newV, rightOp.newV)) {
        return side === 'left' ? [leftOp] : [rightOp];
      }
      return [leftOp];
    }
    default:
      return [leftOp];
  }
};
