import { RangeMan } from '@boss/h-table';
import {
  DimensionMeta,
  Operation,
  UpdateDimensionOperation,
  SparseArray,
  ScatterDimensionOperation,
  Sparse,
  isTrueEmpty,
} from '@bzl/sheet-js';
import produce from 'immer';

export const transScatterDimension = (
  leftOp: ScatterDimensionOperation,
  rightOp: Operation,
  side: 'right' | 'left',
): (UpdateDimensionOperation | ScatterDimensionOperation)[] => {
  switch (rightOp.type) {
    case 'scatter-dimension': {
      const rowConflict = rightOp.rows?.length && leftOp.rows?.length;
      const colConflict = rightOp.cols?.length && leftOp.cols?.length;

      if (rowConflict) {
        const leftOpRange = [
          0,
          rightOp.rows![0].index,
          Infinity,
          rightOp.rows![rightOp.rows!.length - 1].index,
        ];
        const rightOpRange = [
          0,
          rightOp.rows![0].index,
          Infinity,
          rightOp.rows![rightOp.rows!.length - 1].index,
        ];
        if (!RangeMan.isOverlapping(rightOpRange, leftOpRange)) {
          return [leftOp];
        }
        const dimensionMeta: SparseArray<DimensionMeta> = [];
        leftOp.rows!.forEach((row) => {
          const [exist] = Sparse.findIndex(rightOp.rows!, row.index);
          if (isTrueEmpty(exist)) {
            dimensionMeta.push(row);
          } else {
            dimensionMeta.push({
              index: row.index,
              meta: side === 'left' ? row.meta : rightOp.rows![exist].meta,
            });
          }
        });

        return [
          {
            type: 'scatter-dimension',
            id: leftOp.id,
            rows: dimensionMeta,
          },
        ];
      }

      if (colConflict) {
        const leftOpRange = [
          rightOp.cols![0].index,
          0,
          rightOp.cols![rightOp.cols!.length - 1].index,
          Infinity,
        ];
        const rightOpRange = [
          rightOp.cols![0].index,
          0,
          rightOp.cols![rightOp.cols!.length - 1].index,
          Infinity,
        ];
        if (!RangeMan.isOverlapping(rightOpRange, leftOpRange)) {
          return [leftOp];
        }
        const dimensionMeta: SparseArray<DimensionMeta> = [];
        leftOp.cols!.forEach((col) => {
          const [exist] = Sparse.findIndex(rightOp.cols!, col.index);
          if (isTrueEmpty(exist)) {
            dimensionMeta.push(col);
          } else {
            dimensionMeta.push({
              index: col.index,
              meta: side === 'left' ? col.meta : rightOp.cols![exist].meta,
            });
          }
        });
        return [
          {
            type: 'scatter-dimension',
            id: leftOp.id,
            cols: dimensionMeta,
          },
        ];
      }
      return [leftOp];
    }
    case 'insert-row':
    case 'insert-col': {
      if (leftOp.rows?.length && rightOp.type === 'insert-row') {
        const newRows = produce(leftOp.rows, (rows) => {
          rows.forEach((row) => {
            if (row.index >= rightOp.at) {
              row.index += rightOp.count;
            }
          });
        });
        return [{ ...leftOp, rows: newRows }];
      }

      if (leftOp.cols?.length && rightOp.type === 'insert-col') {
        const newCols = produce(leftOp.cols, (cols) => {
          cols.forEach((col) => {
            if (col.index >= rightOp.at) {
              col.index += rightOp.count;
            }
          });
        });
        return [{ ...leftOp, cols: newCols }];
      }
      return [leftOp];
    }
    case 'remove-row':
    case 'remove-col': {
      if (leftOp.rows?.length && rightOp.type === 'remove-row') {
        const rows = leftOp.rows
          .filter((row) => row.index < rightOp.at || row.index >= rightOp.at + rightOp.count)
          .map((row) => {
            if (row.index >= rightOp.at + rightOp.count) {
              return {
                ...row,
                index: row.index - rightOp.count,
              };
            }
            return row;
          });
        return rows.length ? [{ ...leftOp, rows }] : [];
      }

      if (leftOp.cols?.length && rightOp.type === 'remove-col') {
        const cols = leftOp.cols
          .filter((col) => col.index < rightOp.at || col.index >= rightOp.at + rightOp.count)
          .map((col) => {
            if (col.index >= rightOp.at + rightOp.count) {
              return {
                ...col,
                index: col.index - rightOp.count,
              };
            }
            return col;
          });
        return cols.length ? [{ ...leftOp, cols }] : [];
      }
      return [leftOp];
    }
    default:
      return [leftOp];
  }
};
