import { RangeMan } from '@boss/h-table';
import {
  DimensionMeta,
  Operation,
  UpdateDimensionOperation,
  SparseArray,
  ScatterDimensionOperation,
  Sparse,
  isTrueEmpty,
} from '@bzl/sheet-js';

export const transUpdateDimension = (
  leftOp: UpdateDimensionOperation,
  rightOp: Operation,
  side: 'right' | 'left',
): (UpdateDimensionOperation | ScatterDimensionOperation)[] => {
  const { from, to, isRow } = leftOp.section;
  switch (rightOp.type) {
    case 'scatter-dimension': {
      const rowConflict = rightOp.rows?.length && leftOp.section.isRow;
      const colConflict = rightOp.cols?.length && !leftOp.section.isRow;

      if (rowConflict) {
        const leftOpRange = [0, leftOp.section.from, Infinity, leftOp.section.to];
        const rightOpRange = [
          0,
          rightOp.rows![0].index,
          Infinity,
          rightOp.rows![rightOp.rows!.length - 1].index,
        ];
        if (!RangeMan.isOverlapping(rightOpRange, leftOpRange)) {
          return [leftOp];
        }
        const dimensionMeta: SparseArray<DimensionMeta> = [];
        for (let i = leftOp.section.from; i <= leftOp.section.to; i++) {
          const [exist] = Sparse.findIndex(rightOp.rows!, i);
          if (isTrueEmpty(exist)) {
            dimensionMeta.push({ index: i, meta: leftOp.meta });
          } else {
            dimensionMeta.push({ index: i, meta: rightOp.rows![exist].meta });
          }
        }
        return [
          {
            type: 'scatter-dimension',
            id: leftOp.id,
            rows: dimensionMeta,
          },
        ];
      }

      if (colConflict) {
        const leftOpRange = [leftOp.section.from, 0, leftOp.section.to, Infinity];
        const rightOpRange = [
          rightOp.cols![0].index,
          0,
          rightOp.cols![rightOp.cols!.length - 1].index,
          Infinity,
        ];
        if (!RangeMan.isOverlapping(rightOpRange, leftOpRange)) {
          return [leftOp];
        }
        const dimensionMeta: SparseArray<DimensionMeta> = [];
        for (let i = leftOp.section.from; i <= leftOp.section.to; i++) {
          const [exist] = Sparse.findIndex(rightOp.cols!, i);
          if (isTrueEmpty(exist)) {
            dimensionMeta.push({ index: i, meta: leftOp.meta });
          } else {
            dimensionMeta.push({ index: i, meta: rightOp.cols![exist].meta });
          }
        }
        return [
          {
            type: 'scatter-dimension',
            id: leftOp.id,
            cols: dimensionMeta,
          },
        ];
      }
      return [leftOp];
    }
    case 'update-dimension': {
      // 行列不冲突
      if (leftOp.section.isRow !== rightOp.section.isRow) {
        return [leftOp];
      }
      // 不相交
      if (leftOp.section.to < rightOp.section.from || leftOp.section.from > rightOp.section.to) {
        return [leftOp];
      }

      const dimensionMeta: SparseArray<DimensionMeta> = [];
      for (let i = from; i <= to; i++) {
        if (i >= rightOp.section.from || i <= rightOp.section.to) {
          // 相交，根据 side 判断
          dimensionMeta.push({ index: i, meta: side === 'left' ? leftOp.meta : rightOp.meta });
        } else {
          // 不相交，以 leftOp 为准
          dimensionMeta.push({ index: i, meta: leftOp.meta });
        }
      }

      return [
        {
          id: leftOp.id,
          type: 'scatter-dimension',
          [isRow ? 'rows' : 'cols']: dimensionMeta,
        },
      ];
    }
    case 'insert-row':
    case 'insert-col': {
      if (leftOp.section.isRow && rightOp.type === 'insert-col') {
        return [leftOp];
      }
      if (!leftOp.section.isRow && rightOp.type === 'insert-row') {
        return [leftOp];
      }
      if (rightOp.at > leftOp.section.to) {
        return [leftOp];
      }

      if (rightOp.at < leftOp.section.from) {
        return [
          {
            ...leftOp,
            section: {
              ...leftOp.section,
              from: leftOp.section.from + rightOp.count,
              to: leftOp.section.to + rightOp.count,
            },
          },
        ];
      }

      if (rightOp.at === leftOp.section.from) {
        return [
          {
            ...leftOp,
            section:
              rightOp.follow === 'after'
                ? {
                    ...leftOp.section,
                    to: leftOp.section.to + rightOp.count,
                  }
                : {
                    ...leftOp.section,
                    from: leftOp.section.from + rightOp.count,
                    to: leftOp.section.to + rightOp.count,
                  },
          },
        ];
      }

      if (rightOp.at === leftOp.section.to) {
        return [
          {
            ...leftOp,
            section:
              rightOp.follow === 'before'
                ? {
                    ...leftOp.section,
                    to: leftOp.section.to + rightOp.count,
                  }
                : leftOp.section,
          },
        ];
      }

      return [
        {
          ...leftOp,
          section: {
            ...leftOp.section,
            to: leftOp.section.to + rightOp.count,
          },
        },
      ];
    }
    case 'remove-row':
    case 'remove-col': {
      if (leftOp.section.isRow && rightOp.type === 'remove-col') {
        return [leftOp];
      }
      if (!leftOp.section.isRow && rightOp.type === 'remove-row') {
        return [leftOp];
      }
      const removeColRange = [rightOp.at, 0, rightOp.at + rightOp.count - 1, Infinity];
      const leftOpRange = [leftOp.section.from, 0, leftOp.section.to, Infinity];
      if (!RangeMan.isOverlapping(removeColRange, leftOpRange)) {
        if (leftOp.section.from >= rightOp.at + rightOp.count) {
          return [
            {
              ...leftOp,
              section: {
                ...leftOp.section,
                from: leftOp.section.from - rightOp.count,
                to: leftOp.section.to - rightOp.count,
              },
            },
          ];
        } else {
          return [leftOp];
        }
      }
      if (RangeMan.isFullOverlapping(removeColRange, leftOpRange)) {
        return [];
      }
      if (RangeMan.isFullOverlapping(leftOpRange, removeColRange)) {
        return [
          {
            ...leftOp,
            section: {
              ...leftOp.section,
              to: leftOp.section.to - rightOp.count,
            },
          },
        ];
      }
      return [
        {
          ...leftOp,
          section:
            removeColRange[2] > leftOp.section.to
              ? {
                  ...leftOp.section,
                  to: rightOp.at,
                }
              : { ...leftOp.section, from: rightOp.at },
        },
      ];
    }
    default:
      return [leftOp];
  }
};
