import { Operation, InsertColOperation } from '@bzl/sheet-js';

export const transInsertCol = (
  leftOp: InsertColOperation,
  rightOp: Operation,
  side: 'right' | 'left',
): InsertColOperation[] => {
  switch (rightOp.type) {
    case 'insert-col':
      if (rightOp.at > leftOp.at) {
        return [leftOp];
      }
      if (rightOp.at === leftOp.at && side === 'left') {
        return [leftOp];
      }

      return [
        {
          ...leftOp,
          at: leftOp.at + rightOp.count,
        },
      ];
    case 'remove-col': {
      if (leftOp.at <= rightOp.at) {
        return [leftOp];
      }
      if (leftOp.at >= rightOp.at + rightOp.count) {
        return [
          {
            ...leftOp,
            at: Math.max(leftOp.at - rightOp.count, 0),
          },
        ];
      }
      if (leftOp.at + leftOp.count > rightOp.at + rightOp.count) {
        return [
          {
            ...leftOp,
            at: rightOp.at,
            count: leftOp.at + leftOp.count - (rightOp.at + rightOp.count),
          },
        ];
      }
      return [];
    }
    default:
      return [leftOp];
  }
};
