import { RangeMan } from '@boss/h-table';
import { Operation, CreateFilterOperation } from '@bzl/sheet-js';

export const transCreateFilter = (
  leftOp: CreateFilterOperation,
  rightOp: Operation,
  side: 'right' | 'left',
): Operation[] => {
  switch (rightOp.type) {
    case 'create-filter':
    case 'remove-filter': {
      return side === 'left' ? [leftOp] : [rightOp];
    }
    case 'insert-col': {
      if (rightOp.at <= leftOp.range[2]) {
        const newRange = RangeMan.applyInsertCol(leftOp.range, {
          at: rightOp.at,
          count: rightOp.count,
        });
        const newRule = leftOp.cols.map((col) =>
          col.index >= rightOp.at ? { ...col, index: col.index + rightOp.count } : col,
        );
        return [
          {
            ...leftOp,
            range: newRange,
            cols: newRule,
          },
        ];
      }
      return [leftOp];
    }

    case 'remove-col': {
      const newRange = RangeMan.applyRemoveCol(leftOp.range, {
        at: rightOp.at,
        count: rightOp.count,
      });

      if (newRange) {
        const newRule = leftOp.cols
          .filter((col) => col.index < rightOp.at || col.index >= rightOp.at + rightOp.count)
          .map((col) =>
            col.index >= rightOp.at + rightOp.count
              ? {
                  ...col,
                  index: Math.max(col.index - rightOp.count, 0),
                }
              : col,
          );
        return [
          {
            ...leftOp,
            range: newRange,
            cols: newRule,
          },
        ];
      }
      return [];
    }
    case 'insert-row': {
      const newRange = RangeMan.applyInsertRow(leftOp.range, {
        at: rightOp.at,
        count: rightOp.count,
      });
      return [
        {
          ...leftOp,
          range: newRange,
        },
      ];
    }
    case 'remove-row': {
      const newRange = RangeMan.applyRemoveRow(leftOp.range, {
        at: rightOp.at,
        count: rightOp.count,
      });
      if (newRange) {
        return [
          {
            ...leftOp,
            range: newRange,
          },
        ];
      }
      return [];
    }
    default:
      return [leftOp];
  }
};
