import { Operation } from '@bzl/sheet-js';
import { doTransform } from '../doTransform';

export function xTransform1x1(
  leftOp: Operation,
  rightOp: Operation,
  side: 'left' | 'right',
): [Operation[], Operation[]] {
  const other = side === 'left' ? 'right' : 'left';
  return [doTransform(leftOp, rightOp, side), doTransform(rightOp, leftOp, other)];
}
