import { Operation } from '@bzl/sheet-js';
import { xTransformMxN } from './xTransformMxN';
import { xTransform1x1 } from './xTransform1x1';

export function xTransform1xN(
  leftOp: Operation,
  rightOps: Operation[],
  side: 'left' | 'right',
): [Operation[], Operation[]] {
  let rRes: Operation[] = [];

  for (let n = 0; n < rightOps.length; n++) {
    const rightOp: Operation = rightOps[n];

    let [l, r] = xTransform1x1(leftOp, rightOp, side);
    rRes = rRes.concat(r);

    if (l.length === 0) {
      rRes = rRes.concat(rightOps.slice(n + 1));
      return [[], rRes];
    }

    if (l.length > 1) {
      [l, r] = xTransformMxN(l, rightOps.slice(n + 1), side);
      rRes = rRes.concat(r);
      return [l, rRes];
    }

    // l.length == 1
    leftOp = l?.[0];
  }
  return [[leftOp], rRes];
}
