import { Cell, Operation, UpdateCellOperation } from '@bzl/sheet-js';

export const transUpdateCell = (
  leftOp: UpdateCellOperation,
  rightOp: Operation,
  side: 'right' | 'left',
): UpdateCellOperation[] => {
  const [r, c] = leftOp.at;
  switch (rightOp.type) {
    case 'sort': {
      const { range, after, before } = rightOp;
      if (r > range[3] || r < range[1]) {
        return [leftOp];
      }
      const idx = after.findIndex((i) => i === r);
      const newR = idx === -1 ? r : before[idx];
      return [
        {
          ...leftOp,
          at: [newR, c],
        },
      ];
    }
    case 'insert-row':
      if (r < rightOp.at) {
        return [leftOp];
      }

      return [
        {
          ...leftOp,
          at: [r + rightOp.count, c],
        },
      ];
    case 'remove-row': {
      if (r < rightOp.at) {
        return [leftOp];
      }
      if (r >= rightOp.at + rightOp.count) {
        return [
          {
            ...leftOp,
            at: [r - rightOp.count, c],
          },
        ];
      }
      // 被 remove-row 删除了
      return [];
    }
    case 'insert-col': {
      if (c < rightOp.at) {
        return [leftOp];
      }

      return [
        {
          ...leftOp,
          at: [r, c + rightOp.count],
        },
      ];
    }
    case 'remove-col': {
      if (c <= rightOp.at) {
        return [leftOp];
      }
      if (c >= rightOp.at + rightOp.count) {
        return [
          {
            ...leftOp,
            at: [r, c - rightOp.count],
          },
        ];
      }
      // 被 remove-col 删除了
      return [];
    }
    case 'update-cell': {
      const [rr, rc] = rightOp.at;
      if (rr === r && rc === c) {
        return side === 'left'
          ? [
              {
                ...leftOp,
                newV: {
                  ...rightOp.newV,
                  ...leftOp.newV,
                } as Cell,
              },
            ]
          : [
              {
                ...leftOp,
                newV: {
                  ...leftOp.newV,
                  ...rightOp.newV,
                } as Cell,
              },
            ];
      }
      return [leftOp];
    }
    default:
      return [leftOp];
  }
};
