import {
  BaseExtendSparse,
  Cell,
  handleSparseSort,
  Operation,
  ScatterRangeOperation,
  Sparse,
  SparseData,
  SparseMetrix,
  Style,
} from '@bzl/sheet-js';
import { RangeMan } from '@boss/h-table';
import produce from 'immer';

function sortSparseRow(
  rows: SparseMetrix<Style | Cell>,
  options: { after: number[]; before: number[] },
): SparseMetrix<Style | Cell> {
  return produce(rows, (draft) => {
    draft.forEach((row) => {
      const rowIndex = row.index;
      // 获取排序后的顺序
      const afterIdx = options.after.findIndex((i) => i === rowIndex);
      const sortedRowIndex = afterIdx === -1 ? rowIndex : options.before[afterIdx]; // effectRange[1] + afterIdx;
      row.index = sortedRowIndex;
    });
    draft.sort(function (a, b) {
      return a.index - b.index;
    });
  });
}

export const transScatterRange = (
  leftOp: ScatterRangeOperation,
  rightOp: Operation,
  side: 'right' | 'left',
): ScatterRangeOperation[] => {
  switch (rightOp.type) {
    // case 'fill-range': {
    //   // 判断是否为冲突类型
    //   const isConflict = rightOp.fillBy === leftOp.scatterBy || rightOp.fillBy === 'clear';

    //   if (isConflict && RangeMan.isOverlapping(leftOp.range, rightOp.range) && side !== 'le') {
    //     // 切分 scatter range
    //     const splitInfo = RangeMan.splitRange(leftOp.range, rightOp.range);
    //     if (splitInfo) {
    //       return splitInfo.source
    //         .map((r) => {
    //           // 判断 两者op 是否都包含sheet的设置
    //           const sheetConflict = isFullSheetRange(rightOp.range) && 'sheet' in leftOp.refs;
    //           const op = {
    //             ...leftOp,
    //             range: r,
    //             refs: {
    //               rows: leftOp.refs.rows ? Sparse.getRange(leftOp.refs.rows, r) : undefined,
    //               cols: leftOp.refs.cols?.filter((c) => c.index <= r[2] && c.index >= r[0]),
    //             },
    //           } as ScatterRangeOperation;
    //           // 如果 sheet 设置不冲突，则保留 sheet 的设置
    //           if (!sheetConflict) {
    //             op.refs.sheet = leftOp.refs.sheet;
    //           }
    //           return op;
    //         })
    //         .filter((op) => op.refs.rows);
    //     }
    //   }
    //   return [leftOp];
    // }
    case 'scatter-range': {
      const isConflict = rightOp.scatterBy === leftOp.scatterBy;
      if (isConflict && RangeMan.isOverlapping(leftOp.range, rightOp.range) && side !== 'left') {
        // 切分 scatter range
        const splitInfo = RangeMan.splitRange(leftOp.range, rightOp.range);
        if (splitInfo) {
          return splitInfo.source
            .map((r) => {
              // 判断 两者op 是否都包含sheet的设置
              const sheetConflict = 'sheet' in rightOp.refs && 'sheet' in leftOp.refs;
              const op = {
                ...leftOp,
                range: r,
                refs: {
                  rows: leftOp.refs.rows ? Sparse.getRange(leftOp.refs.rows, r) : undefined,
                  cols: leftOp.refs.cols?.filter((c) => c.index <= r[2] && c.index >= r[0]),
                },
              } as ScatterRangeOperation;
              // 如果 sheet 设置不冲突，则保留 sheet 的设置
              if (!sheetConflict) {
                op.refs.sheet = leftOp.refs.sheet;
              }
              return op;
            })
            .filter((op) => op.refs.rows);
        }
      }
      return [leftOp];
    }

    case 'insert-col': {
      const newRange = RangeMan.applyInsertCol(leftOp.range, {
        at: rightOp.at,
        count: rightOp.count,
      });
      if (leftOp.refs) {
        const newRefs = produce(leftOp.refs, (refs) => {
          refs.cols = refs.cols ?? [];
          refs.rows = refs.rows ?? [];
          const extendSparse = new BaseExtendSparse(refs as SparseData<Style | Cell>);
          extendSparse.insertCol({
            at: rightOp.at,
            distance: rightOp.count,
            follow: rightOp.follow,
          });
          return extendSparse.data;
        });
        return [
          {
            ...leftOp,
            refs: newRefs,
            range: newRange,
          },
        ];
      }
      return [leftOp];
      // const newLeftOp = produce(leftOp, (op) => {
      //   op.refs.rows?.forEach((row: BaseSparse<any>) => {
      //     row.children?.forEach((cell) => {
      //       cell.index = cell.index >= rightOp.at ? rightOp.count + cell.index : cell.index;
      //     });
      //   });
      //   return op;
      // });
    }
    // 注意：删除列，需要保留 rowMeta 整行样式
    case 'remove-col': {
      const newRefs = produce(leftOp.refs, (refs) => {
        refs.cols = refs.cols ?? [];
        refs.rows = refs.rows ?? [];
        // const extendSparse = new BaseExtendSparse(refs as SparseData<Style | Cell>);
        // extendSparse.deleteCol({ at: rightOp.at, distance: rightOp.count });
        // return extendSparse.data;
        Sparse.deleteCol(
          refs.rows,
          {
            col: rightOp.at,
            distance: rightOp.count,
          },
          false,
        );
        Sparse.deleteRow(refs.cols, {
          row: rightOp.at,
          distance: rightOp.count,
        });
        return refs;
      });
      console.log('newRefs>>>', newRefs);
      return [
        {
          ...leftOp,
          refs: newRefs,
        },
      ];
    }
    case 'insert-row': {
      const newRange = RangeMan.applyInsertRow(leftOp.range, {
        at: rightOp.at,
        count: rightOp.count,
      });

      if (newRange) {
        const newRefs = produce(leftOp.refs, (refs) => {
          refs.cols = refs.cols ?? [];
          refs.rows = refs.rows ?? [];
          const extendSparse = new BaseExtendSparse(refs as SparseData<Style | Cell>);
          extendSparse.insertRow({
            at: rightOp.at,
            distance: rightOp.count,
            follow: leftOp.scatterBy === 'data' ? undefined : rightOp.follow,
          });
          return extendSparse.data;
        });
        return [
          {
            ...leftOp,
            refs: newRefs,
            range: newRange,
          },
        ];
      }
      return [leftOp];
    }
    case 'remove-row': {
      const newRange = RangeMan.applyRemoveRow(leftOp.range, {
        at: rightOp.at,
        count: rightOp.count,
      });
      if (!newRange) {
        return [];
      }
      const newLeftOp = produce(leftOp, (op) => {
        const newRows = op.refs.rows
          ?.filter((r) => r.index < rightOp.at || r.index >= rightOp.at + rightOp.count)
          .map((r) => ({
            ...r,
            index: r.index >= rightOp.at + rightOp.count ? r.index - rightOp.count : r.index,
          }));
        op.refs.rows = newRows;
      });

      return [
        {
          ...newLeftOp,
          range: newRange,
        },
      ];
    }
    case 'sort': {
      const { range, sortBy, before, after } = rightOp;
      const effectRange = sortBy === 'sheet' ? [0, range[1], Infinity, range[3]] : range;

      // scatter range 覆盖 sort range，进行切割，只对重叠部分进行排序
      if (RangeMan.isFullOverlapping(leftOp.range, effectRange) && leftOp.refs.rows) {
        leftOp.refs = produce(leftOp.refs, (draft) => {
          // eslint-disable-next-line @typescript-eslint/ban-ts-comment
          // @ts-ignore
          handleSparseSort(draft, leftOp.refs, {
            range: effectRange,
            sortBy,
            after,
            before,
          });
        });
        return [leftOp];
      }

      // scatter range 被完全覆盖，直接进行排序
      if (RangeMan.isOverlapping(effectRange, leftOp.range) && leftOp.refs.rows) {
        // 将scatterRange内的行进行重新定位排序
        leftOp.refs.rows = sortSparseRow(leftOp.refs.rows, { after, before });
        // 扩充 range
        leftOp.range = [
          leftOp.range[0],
          leftOp.refs.rows[0].index,
          leftOp.range[2],
          leftOp.refs.rows[leftOp.refs.rows.length - 1].index,
        ];
        return [leftOp];
      }

      return [leftOp];
    }
    default:
      return [leftOp];
  }
};
