import { Operation } from '@bzl/sheet-js';
import { xTransform1xN } from './xTransform1xN';

export function xTransformMxN(
  leftOps: Operation[],
  rightOps: Operation[],
  side: 'left' | 'right',
): [Operation[], Operation[]] {
  let leftRes: Operation[] = [];

  for (let m = 0; m < leftOps.length; m++) {
    const leftOp: Operation = leftOps[m];

    const [lRes, rRes] = xTransform1xN(leftOp, rightOps, side);

    leftRes = leftRes.concat(lRes);

    rightOps = rRes;
  }

  return [leftRes, rightOps];
}
